import json
import os
from typing import Iterator, Optional, Union
import boto3
from botocore.exceptions import NoCredentialsError, ClientError

class InputReader:
    def __init__(self, source: Union[str, dict], fail_on_missing: bool = False):
        self.fail_on_missing = fail_on_missing
        if isinstance(source, str):
            self.source = source
            self.is_json = False
        elif isinstance(source, dict):
            self.source = source
            self.is_json = True
        else:
            raise ValueError("Source must be a string or a dictionary.")

    def _read_file(self, file_path: str) -> Iterator[str]:
        if not os.path.exists(file_path):
            if self.fail_on_missing:
                raise FileNotFoundError(f"File not found: {file_path}")
            else:
                return iter([])

        with open(file_path, 'r') as file:
            for line in file:
                yield line

    def _read_bucket(self, bucket_name: str, object_key: str) -> Iterator[str]:
        s3 = boto3.client('s3')
        try:
            response = s3.get_object(Bucket=bucket_name, Key=object_key)
            for line in response['Body'].iter_lines():
                yield line.decode('utf-8')
        except (NoCredentialsError, ClientError) as e:
            if self.fail_on_missing:
                raise e
            else:
                return iter([])

    def __iter__(self) -> Iterator[str]:
        if self.is_json:
            source = self.source
        else:
            source = json.loads(self.source)

        if 'file_path' in source:
            return self._read_file(source['file_path'])
        elif 'bucket_name' in source and 'object_key' in source:
            return self._read_bucket(source['bucket_name'], source['object_key'])
        else:
            raise ValueError("Invalid source format. Must contain 'file_path' or 'bucket_name' and 'object_key'.")

    @classmethod
    def from_json(cls, json_str: str, fail_on_missing: bool = False) -> 'InputReader':
        source = json.loads(json_str)
        return cls(source, fail_on_missing)

    def to_json(self) -> str:
        if self.is_json:
            return json.dumps(self.source)
        else:
            if 'file_path' in self.source:
                return json.dumps({'file_path': self.source['file_path']})
            elif 'bucket_name' in self.source and 'object_key' in self.source:
                return json.dumps({'bucket_name': self.source['bucket_name'], 'object_key': self.source['object_key']})
            else:
                raise ValueError("Invalid source format. Must contain 'file_path' or 'bucket_name' and 'object_key'.")
